import{_ as a,o as e,c as s}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Page 21 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"21","title":"Page 21 | Home","prev":"/page/20/","next":"/page/22/","posts":[{"title":"跨域请求中的cookies处理","url":"/posts/2018-09-08-cors-cookie/","date":"2018-09-08 23:07","tags":["cors","cookies"],"html":"<p>现在的前后端开发已经完全分离，后端服务器和前端服务器分别部署在不同的服务器。同时也对应不同的域名，所以跨域请求领域方面的知识也需要补充。</p>\\n<h2 id=\\"跨域请求添加-header\\" tabindex=\\"-1\\">跨域请求添加 header <a class=\\"header-anchor\\" href=\\"#跨域请求添加-header\\" aria-label=\\"Permalink to &quot;跨域请求添加 header&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们都知道，出于安全考虑，JS 是有同源策略限制。所以，我们在对其他域名发起请求的时候需要添加 http header。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Access-Control-Allow-Origin: *</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个参数的值只能为星号或者具体的网址，星号代表所有网站。</p>\\n<h2 id=\\"跨域请求添加-cookie\\" tabindex=\\"-1\\">跨域请求添加 cookie <a class=\\"header-anchor\\" href=\\"#跨域请求添加-cookie\\" aria-label=\\"Permalink to &quot;跨域请求添加 cookie&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JS 跨域请求有两个 API 可以使用，<code>XMLHttpRequest</code>和<code>fetch</code>。<code>XMLHttpRequest</code>会默认带上 cookies，但是<code>fetch</code>默认不会带上。如果需要带上 cookies，需要把<code>withCredentials</code>设置为<code>true</code>。</p>\\n<h2 id=\\"跨域请求服务器设置-cookie\\" tabindex=\\"-1\\">跨域请求服务器设置 cookie <a class=\\"header-anchor\\" href=\\"#跨域请求服务器设置-cookie\\" aria-label=\\"Permalink to &quot;跨域请求服务器设置 cookie&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们都知道服务器设置 cookie 是通过<code>set-cookie</code>的 http header 来完成。浏览器会读取这个信息设置 cookie。但是对于跨与请求，默认是无效的。我们需要再添加一个 http header。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Access-Control-Allow-Credentials: true</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>当设置了这个 http header，<code>Access-Control-Allow-Origin</code>就不能设置为星号了，必须指定具体的网址。我们必须指定<code>withCredentials</code>为<code>true</code>并且<code>Access-Control-Allow-Credentials</code>为<code>true</code>的时候，服务器返回的<code>set-cookie</code>才会生效。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Access-Control-Allow-Credentials\\" target=\\"_blank\\" rel=\\"noreferrer\\">Access-Control-Allow-Credentials</a></p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS\\" target=\\"_blank\\" rel=\\"noreferrer\\">CORS</a></p>\\n"},{"title":"伪随机的种子问题","url":"/posts/2018-08-01-random-seed/","date":"2018-08-01 22:07","tags":["random","seed"],"html":"<p>最近前端的工作不是很多，所以就帮忙写写后端的 ruby on rails。在写测试用例的时候，虽然单元测试的数据每次都是随机生成的，但是我们需要根据单元测试来生成 API 文档。如果测试文档每次都是随机的数据会很难检查每次 API 更新了什么，所以我们需要在生产测试文档的时候，保证随机数据的稳定性。</p>\\n<h2 id=\\"random-seed\\" tabindex=\\"-1\\">Random seed <a class=\\"header-anchor\\" href=\\"#random-seed\\" aria-label=\\"Permalink to &quot;Random seed&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>seed 的意义就在于，初始化了随机数生成器。保证了每次随机的结果都一样。例如代码：</p>\\n<div class=\\"language-rb line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">rb</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">@rand </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> Random</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#D73A49\\">new</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1234</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">1050</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">1050</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>这段代码每次执行都会输出：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>0.1915194503788923</span></span>\\n<span class=\\"line\\"><span>674</span></span>\\n<span class=\\"line\\"><span>699</span></span>\\n<span class=\\"line\\"><span>0.2725926052826416</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"rand-range\\" tabindex=\\"-1\\">rand range <a class=\\"header-anchor\\" href=\\"#rand-range\\" aria-label=\\"Permalink to &quot;rand range&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>但是当我们把中间的 rand 的范围稍微修改：</p>\\n<div class=\\"language-rb line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">rb</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">@rand </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> Random</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#D73A49\\">new</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1234</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">150</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">..</span><span style=\\"color:#005CC5\\">150</span><span style=\\"color:#24292E\\">)</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">puts</span><span style=\\"color:#24292E\\"> @rand.</span><span style=\\"color:#005CC5\\">rand</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>会发现输出发生了变化：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>0.1915194503788923</span></span>\\n<span class=\\"line\\"><span>48</span></span>\\n<span class=\\"line\\"><span>63</span></span>\\n<span class=\\"line\\"><span>0.4377277390071145</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>第一次的输出还是不变，当然 2,3 两次肯定是变化的，重点是最后一次。我们发现最后一次的随机数也发生了变化。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>通过调查 ruby 源码发现，对于有范围的 rand。ruby 会不断生成随机数，判断是否落在区间范围内，如果是在范围内就返回，否则继续尝试。默认在 0 到 1 之间是百分百命中，所以是随机一次。如果是其他范围，命中次数不一样会导致生成随机数的次数发生变化。所以影响到之后的随机数生成。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/ruby/ruby/blob/trunk/random.c#L863\\" target=\\"_blank\\" rel=\\"noreferrer\\">ruby</a></p>\\n<p><a href=\\"https://ruby-doc.org/core-2.2.0/Random.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Random</a></p>\\n"},{"title":"Web离线的解决方案","url":"/posts/2018-07-06-offline-web/","date":"2018-07-06 23:25","tags":["web","offline"],"html":"<p>最近的工作是做嵌入在 iOS 程序内部的页面，其中有一个需求就是需要满足在离线的情况下显示页面。当然，现在主流的离线方式是使用 Service Worker 来完成离线需求。\\n但是 iOS 内置的 WKWebView 并不支持最新的 Service Worker（取决于 iOS 版本）最新版本已经支持，所以不得不想办法来解决。</p>\\n<h2 id=\\"application-cache\\" tabindex=\\"-1\\">Application Cache <a class=\\"header-anchor\\" href=\\"#application-cache\\" aria-label=\\"Permalink to &quot;Application Cache&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>AppCache 是一个过时的技术，但是在 iOS 下勉强还能用。不过 Chrome 对这种过时的技术支持不是很好，单个缓存文件最大只支持 5MB。而且还有请求的 BUG:<a href=\\"https://bugs.chromium.org/p/chromium/issues/detail?id=140445\\" target=\\"_blank\\" rel=\\"noreferrer\\">Accept header on GET request for appcache manifest</a>。触发 AppCache 是在 html 标签中添加 manifest 属性。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#6F42C1\\"> manifest</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"manifest.appcache\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ...</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#22863A\\">html</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>通过<code>manifest.appcache</code>文件来定义需要缓存的文件，不过载入<code>manifest.appcache</code>的页面会被作为<code>Master entries</code>缓存起来。因为 AppCache 出现的时候还是以静态网站为主，所以并不能缓存请求的 Ajax 数据。我们需要自己再手动实现缓存所有请求在<code>localStorage</code>，但是<code>localStorage</code>同样也有最大 5MB 的限制。所以也需要考虑相应的解决方案。不过，我最终采取的方式是通过嵌入<code>iframe</code>来实现触发 AppCache，这样做的好处是因为 SPA 应用是自己来控制路由的，所以导致每个路径都会保存一份<code>Master entries</code>。但是通过 iframe 的话，我们的<code>Master entries</code>永远只有一份。并且当前页面的所有资源也被顺利缓存，因为 SPA 无论访问哪个路径返回的都是相同的<code>index.html</code>。由 JS 来控制路由并加载相应的组件。</p>\\n<p>这里要补充的一点是，针对 https 的 Application Cache 是无法完成跨域请求的，所以请慎重。</p>\\n<h2 id=\\"workbox\\" tabindex=\\"-1\\">WorkBox <a class=\\"header-anchor\\" href=\\"#workbox\\" aria-label=\\"Permalink to &quot;WorkBox&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Service Worker 是现在主流的缓存技术，会帮你缓存所有的静态文件和数据请求。但是对于 SPA 项目，我们不可能自己手动书写缓存清单。所以还是借助现有的开源解决方案，这里最出名的解决方案是谷歌的 Workbox。通过使用 Webpack 插件和简单的配置，我们便可以做到缓存所有的静态资源和数据。Service Worker 有很多种缓存策略可以选择，例如 Cache First 和 NetWork First。但是 AppCache 每次都会优先使用缓存，然后再去更新最新的文件。所以我们不得不在发生更新的时候去重新加载页面。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>最终的解决方案是优先使用 Service Worker，当不支持 Service Worker 的时候再回退到 AppCache。但是想要从 AppCache 升级到 Service Worker 的时候，必须清除所有 AppCache 的所有数据。浏览器并没有提供相应的接口，我们目前采用的方式是手动删除 AppCache 储存的数据库来完成这一需求。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Using_the_application_cache\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using the application cache</a></p>\\n<p><a href=\\"https://developer.apple.com/library/archive/documentation/iPhone/Conceptual/SafariJSDatabaseGuide/OfflineApplicationCache/OfflineApplicationCache.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTML5 Offline Application Cache</a></p>\\n<p><a href=\\"https://github.com/lettertwo/appcache-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Application Cache plugin for Webpack</a></p>\\n<p><a href=\\"https://developers.google.com/web/tools/workbox/modules/workbox-webpack-plugin\\" target=\\"_blank\\" rel=\\"noreferrer\\">Workbox webpack Plugins</a></p>\\n<p><a href=\\"https://appcachefacts.info/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Appcache Facts</a></p>\\n"}]},"relativePath":"page/21/index.md","filePath":"page/[page].md"}'),n={name:"page/21/index.md"};function p(l,r,o,c,t,i){return e(),s("div")}const b=a(n,[["render",p]]);export{h as __pageData,b as default};
